use anyhow::{anyhow, Result}; use serde_json::Value; use uuid::Uuid; use crate::namegen::generateName;
pub const vkConnectClientID:&str="8093730"; pub const vkCallsAPIHost:&str="api.vk.me"; pub const vkCallsAnonAPIVersion:&str="5.276";
#[derive(Debug,Clone)] pub struct vkCallsFailure {pub Step:String,pub Kind:String,pub Err:String} impl std::fmt::Display for vkCallsFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{write!(f,"step={} kind={}: {}",self.Step,self.Kind,self.Err)}} impl std::error::Error for vkCallsFailure{}
pub fn newVKCallsFailure(step:&str,kind:&str,err:impl std::fmt::Display)->anyhow::Error{anyhow!(vkCallsFailure{Step:step.into(),Kind:kind.into(),Err:err.to_string()})} pub fn describeVKCallsFailure(err:&anyhow::Error)->String{err.to_string()} pub fn vkCallsAPIErrorKind(_: &anyhow::Error)->&'static str{"vk_api"}
#[derive(Debug)] pub struct vkCallsVKAPIError{pub Code:i64,pub Message:String} impl std::fmt::Display for vkCallsVKAPIError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{write!(f,"error_code={} {}",self.Code,self.Message)}}impl std::error::Error for vkCallsVKAPIError{} #[derive(Debug)]pub struct vkCallsOKAPIError{pub Code:i64,pub Message:String} impl std::fmt::Display for vkCallsOKAPIError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{write!(f,"error_code={} {}",self.Code,self.Message)}}impl std::error::Error for vkCallsOKAPIError{}
pub async fn getVKCredsViaVKCallsPath(link:&str,streamID:i32)->Result<(String,String,Vec<String>)>{if std::env::var("VK_SKIP_VKCALLS").as_deref()==Ok("1"){return Err(newVKCallsFailure("preflight","skipped","disabled by VK_SKIP_VKCALLS=1"))}let c=reqwest::Client::builder().timeout(std::time::Duration::from_secs(20)).build()?;let id=Uuid::new_v4();let name=generateName();let post=|url:String|{let c=c.clone();async move{Ok::<Value,anyhow::Error>(c.post(url).header("User-Agent","Mozilla/5.0").send().await?.error_for_status()?.json().await?)}};let base=format!("https://{vkCallsAPIHost}/method/");let r=post(format!("{base}auth.getAnonymToken?v={vkCallsAnonAPIVersion}&client_id={vkConnectClientID}&link={}&device_id={id}&anonymName={}",url::form_urlencoded::byte_serialize(format!("https://vk.com/call/join/{link}").as_bytes()).collect::<String>(),url::form_urlencoded::byte_serialize(name.as_bytes()).collect::<String>())).await?;let token=extractVKCallsStr(&r,&["response","token"])?;let r=post(format!("{base}messages.getCallPreview?v={vkCallsAnonAPIVersion}&anonymous_token={token}&device_id={id}&link=https%3A%2F%2Fvk.com%2Fcall%2Fjoin%2F{link}")).await?;if let Some(e)=vkCallsAPIError(&r){return Err(e)}let user=extractVKCallsFloat(&r,&["response","user_id"])? as i64;let secret=extractVKCallsStr(&r,&["response","secret"])?;let r=post(format!("{base}messages.getAnonymCallToken?v={vkCallsAnonAPIVersion}&anonymous_token={token}&device_id={id}&link=https%3A%2F%2Fvk.com%2Fcall%2Fjoin%2F{link}&name={}&user_id={user}&secret={}",url::form_urlencoded::byte_serialize(name.as_bytes()).collect::<String>(),url::form_urlencoded::byte_serialize(secret.as_bytes()).collect::<String>())).await?;if let Some(e)=vkCallsAPIError(&r){return Err(e)}let ok_token=extractVKCallsStr(&r,&["response","token"])?;let r=post(format!("https://calls.okcdn.ru/fb.do?method=vchat.joinConversationByLink&format=JSON&application_key=CGMMEJLGDIHBABABA&anonymToken={ok_token}&joinLink={link}&isVideo=false&protocolVersion=5&capabilities=2F7F")).await?;let t=r.get("turn_server").ok_or_else(||anyhow!("missing turn_server"))?;let user=t.get("username").and_then(Value::as_str).ok_or_else(||anyhow!("missing username"))?.into();let pass=t.get("credential").and_then(Value::as_str).ok_or_else(||anyhow!("missing credential"))?.into();let urls=parseVKCallsTURNAddresses(&r);if urls.is_empty(){return Err(anyhow!("no TURN addresses"))}eprintln!("[STREAM {streamID}] [VKCalls] credentials received");Ok((user,pass,urls))}
pub fn extractVKCallsStr(v:&Value,keys:&[&str])->Result<String>{let mut p=v;for k in keys{p=p.get(k).ok_or_else(||anyhow!("missing {}",k))?}p.as_str().map(str::to_string).ok_or_else(||anyhow!("not string"))} pub fn extractVKCallsFloat(v:&Value,keys:&[&str])->Result<f64>{let mut p=v;for k in keys{p=p.get(k).ok_or_else(||anyhow!("missing {}",k))?}p.as_f64().ok_or_else(||anyhow!("not number"))}
pub fn parseVKCallsTURNAddresses(v:&Value)->Vec<String>{v.pointer("/turn_server/urls").and_then(Value::as_array).into_iter().flatten().filter_map(Value::as_str).map(|s|s.split('?').next().unwrap_or(s).trim_start_matches("turn:").trim_start_matches("turns:").into()).collect()} pub fn vkCallsAPIError(v:&Value)->Option<anyhow::Error>{v.get("error").map(|e|anyhow!("VK API error: {e}"))} pub fn vkCallsOKError(v:&Value)->Option<anyhow::Error>{v.get("error_code").map(|e|anyhow!("OK CDN API error: {e}"))} pub fn truncateVKCallsLog(s:&str,n:usize)->String{s.chars().take(n).collect()} pub fn truncateVKCallsResp(v:&Value)->String{truncateVKCallsLog(&v.to_string(),200)}
